import React, { useEffect, useState } from 'react';
import {
    apiLayTinNhanChung,
    apiGuiTinNhanChung,
    apiLayTinNhanRieng,
    apiGuiTinNhanRiengCuDan
} from '../../api/goi_api';

export default function NhanTinCuDan() {
    const user = JSON.parse(localStorage.getItem('user') || '{}');

    const [tab, setTab] = useState('chung');
    const [dsChung, setDsChung] = useState([]);
    const [dsRieng, setDsRieng] = useState([]);
    const [noiDungChung, setNoiDungChung] = useState('');
    const [noiDungRieng, setNoiDungRieng] = useState('');

    const fetchChung = async () => {
        try {
            const data = await apiLayTinNhanChung();
            setDsChung(data || []);
        } catch (error) {
            console.error('Lỗi lấy chat chung:', error);
        }
    };

    const fetchRieng = async () => {
        try {
            if (!user?.so_phong) return;
            const data = await apiLayTinNhanRieng(user.so_phong);
            setDsRieng(data || []);
        } catch (error) {
            console.error('Lỗi lấy chat riêng:', error);
        }
    };

    useEffect(() => {
    fetchChung();
    fetchRieng();
    const interval = setInterval(() => {
        fetchChung();
        fetchRieng();
    }, 3000);

    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

    const handleGuiChung = async () => {
        if (!noiDungChung.trim()) return;

        try {
            await apiGuiTinNhanChung({
                id_nguoi_gui: user.id,
                noi_dung: noiDungChung.trim()
            });
            setNoiDungChung('');
            fetchChung();
        } catch (error) {
            console.error('Lỗi gửi chat chung:', error);
            alert(error.response?.data?.message || 'Gửi tin nhắn thất bại!');
        }
    };

    const handleGuiRieng = async () => {
        if (!noiDungRieng.trim()) return;

        try {
            await apiGuiTinNhanRiengCuDan({
                id_nguoi_gui: user.id,
                noi_dung: noiDungRieng.trim()
            });
            setNoiDungRieng('');
            fetchRieng();
        } catch (error) {
            console.error('Lỗi gửi chat riêng:', error);
            alert(error.response?.data?.message || 'Gửi tin nhắn riêng thất bại!');
        }
    };

    const dsHienTai = tab === 'chung' ? dsChung : dsRieng;
    const noiDung = tab === 'chung' ? noiDungChung : noiDungRieng;
    const setNoiDung = tab === 'chung' ? setNoiDungChung : setNoiDungRieng;

    return (
        <div style={containerStyle}>
            <div style={tabStyle}>
                <button onClick={() => setTab('chung')} style={tab === 'chung' ? activeBtnStyle : btnStyle}>
                    Nhắn tin chung
                </button>
                <button onClick={() => setTab('rieng')} style={tab === 'rieng' ? activeBtnStyle : btnStyle}>
                    Chat với admin
                </button>
            </div>

            <div style={chatBoxStyle}>
                <div style={messagesStyle}>
                    {dsHienTai.length === 0 ? (
                        <div style={emptyStyle}>Chưa có tin nhắn</div>
                    ) : (
                        dsHienTai.map((item) => (
                            <div key={item.id} style={itemStyle}>
                                <div style={nameStyle}>{item.ten_hien_thi}</div>
                                <div style={textStyle}>{item.noi_dung}</div>
                                <div style={timeStyle}>
                                    {new Date(item.thoi_gian_gui).toLocaleString('vi-VN')}
                                </div>
                            </div>
                        ))
                    )}
                </div>

                <div style={inputRowStyle}>
                    <input
                        value={noiDung}
                        onChange={(e) => setNoiDung(e.target.value)}
                        placeholder="Nhập tin nhắn..."
                        style={inputStyle}
                    />
                    <button
                        onClick={tab === 'chung' ? handleGuiChung : handleGuiRieng}
                        style={sendBtnStyle}
                    >
                        Gửi
                    </button>
                </div>
            </div>
        </div>
    );
}

const containerStyle = {
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    gap: '15px',
    height: '100%'
};

const tabStyle = {
    display: 'flex',
    gap: '10px'
};

const btnStyle = {
    padding: '12px 18px',
    borderRadius: '12px',
    border: 'none',
    cursor: 'pointer'
};

const activeBtnStyle = {
    ...btnStyle,
    backgroundColor: '#9b6b6b',
    color: '#fff',
    fontWeight: 'bold'
};

const chatBoxStyle = {
    flex: 1,
    background: 'rgba(255,255,255,0.95)',
    borderRadius: '24px',
    padding: '20px',
    display: 'flex',
    flexDirection: 'column'
};

const messagesStyle = {
    flex: 1,
    overflowY: 'auto',
    display: 'flex',
    flexDirection: 'column',
    gap: '12px'
};

const itemStyle = {
    background: '#f8f8f8',
    borderRadius: '14px',
    padding: '12px'
};

const nameStyle = {
    fontWeight: 'bold',
    color: '#8b5e5e'
};

const textStyle = {
    marginTop: '4px',
    color: '#333'
};

const timeStyle = {
    marginTop: '6px',
    fontSize: '12px',
    color: '#888'
};

const inputRowStyle = {
    display: 'flex',
    gap: '10px',
    marginTop: '15px'
};

const inputStyle = {
    flex: 1,
    padding: '14px',
    borderRadius: '12px',
    border: '1px solid #ddd',
    outline: 'none'
};

const sendBtnStyle = {
    padding: '14px 22px',
    borderRadius: '12px',
    border: 'none',
    backgroundColor: '#9b6b6b',
    color: '#fff',
    fontWeight: 'bold',
    cursor: 'pointer'
};

const emptyStyle = {
    flex: 1,
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    color: '#aaa'
};
